EXPECTED_SET=[('btree_gist','1.7','public'),('pgcrypto','1.3','extensions'),('uuid-ossp','1.1','extensions')]
EXPECTED_COUNTS={'btree_gist':{'pg_proc':188,'pg_type':12,'pg_operator':12,'pg_opclass':26,'pg_opfamily':26},'pgcrypto':{'pg_proc':36},'uuid-ossp':{'pg_proc':10}}
class GlobalValidityError(Exception):pass
class ProofFailure(Exception):pass

def profile(e,bootstrap,roles):
    if not e['extensions']:return 'PLPGSQL_ONLY'
    if sorted((x['name'],x['version'],x['schema']) for x in e['extensions'])!=EXPECTED_SET:raise ProofFailure('EXTENSION_SET_VERSION_SCHEMA')
    if any(x['owner']!=bootstrap for x in e['extensions']):raise ProofFailure('EXTENSION_OWNER')
    found=[r for r in roles if r[0]==bootstrap]
    if len(found)!=1 or found[0][1] is not True:raise ProofFailure('BOOTSTRAP_SUPERUSER')
    if any(r[0]==mt.OWNED_RESTORE_ADMIN for r in roles):raise ProofFailure('TRANSPORT_COLLISION')
    counts=collections.defaultdict(collections.Counter)
    identities=set()
    for m in e['members']:
        counts[m['extension']][m['class']]+=1
        key=(m['extension'],m['class'],m['identity'],m['subid'])
        if key in identities or not m['identity'] or m['subid']!=0 or m['structure'] is None:raise ProofFailure('MEMBER_STRUCTURE')
        identities.add(key)
        if m['owner']!=bootstrap:raise ProofFailure('MEMBER_OWNER')
    if {k:dict(v) for k,v in counts.items()}!=EXPECTED_COUNTS:raise ProofFailure('MEMBER_FAMILIES')
    for ext,cls,ident,owner,acl in e['rawAcl']:
        if cls=='pg_type' and acl is not None:raise ProofFailure('TYPE_ACL')
    names={r[0] for r in roles}|{'PUBLIC'}
    for ext,cls,ident,grantor,grantee,priv,option in e['expandedAcl']:
        if grantor!=bootstrap or grantee not in names or option or priv!=('EXECUTE' if cls=='pg_proc' else 'USAGE'):raise ProofFailure('MEMBER_ACL_PROFILE')
    return 'BOOTSTRAP_OWNED_FIXED_EXTENSION_SET'

def archive_statements(raw):
    # Detached read-only archive lexer. Never reserializes execution bytes.
    # Handles COPY payload, standard/E strings, dollar bodies, quoted names and nested comments.
    text=raw.decode('utf8'); n=len(text);i=0;start=None;tokens=[];out=[];meta=[]
    def end_statement(end):
        nonlocal start,tokens
        fragment=text[start:end];b0=len(text[:start].encode());b1=len(text[:end].encode())
        upper=' '.join(tokens).upper()
        row={'byteSpan':[b0,b1],'sha256':sha(raw[b0:b1]),'leadingTokens':tokens[:8]}
        category=None
        if upper.startswith(('SET ROLE','RESET ROLE','SET SESSION AUTHORIZATION','RESET SESSION AUTHORIZATION')):category='identity'
        elif upper.startswith('CREATE EXTENSION'):category='extension'
        elif upper.startswith('CREATE SCHEMA'):category='namespace'
        elif upper.startswith(('GRANT ','REVOKE ','ALTER DEFAULT PRIVILEGES')):category='acl'
        if category:row.update(category=category,sql=fragment);out.append(row)
        iscopy=upper.startswith('COPY ') and 'FROM STDIN' in upper
        start=None;tokens=[]
        return iscopy
    while i<n:
        if text[i].isspace():i+=1;continue
        if text.startswith('--',i):
            j=text.find('\n',i);i=n if j<0 else j+1;continue
        if text.startswith('/*',i):
            depth=1;i+=2
            while i<n and depth:
                if text.startswith('/*',i):depth+=1;i+=2
                elif text.startswith('*/',i):depth-=1;i+=2
                else:i+=1
            if depth:raise GlobalValidityError('ARCHIVE_BLOCK_COMMENT')
            continue
        if start is None and text[i]=='\\':
            j=text.find('\n',i);j=n if j<0 else j
            line=text[i:j]
            if not re.fullmatch(r'\\(?:un)?restrict [A-Za-z0-9]+',line):raise GlobalValidityError('ARCHIVE_META_UNSUPPORTED '+line[:80])
            meta.append({'line':line,'byteOffset':len(text[:i].encode())});i=j;continue
        if start is None:start=i
        ch=text[i]
        if ch in "'\"":
            quote=ch;esc=ch=="'" and i>0 and text[i-1] in 'eE' and (i<2 or not(text[i-2].isalnum() or text[i-2]=='_'))
            i+=1
            while i<n:
                if esc and text[i]=='\\':i+=2
                elif text[i]==quote:
                    if i+1<n and text[i+1]==quote:i+=2
                    else:i+=1;break
                else:i+=1
            else:raise GlobalValidityError('ARCHIVE_QUOTE')
            continue
        if ch=='$':
            m=re.match(r'\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$',text[i:])
            if m:
                tag=m.group();j=text.find(tag,i+len(tag))
                if j<0:raise GlobalValidityError('ARCHIVE_DOLLAR')
                i=j+len(tag);continue
        if ch==';':
            iscopy=end_statement(i+1);i+=1
            if iscopy:
                if i<n and text[i]=='\r':i+=1
                if i<n and text[i]=='\n':i+=1
                while i<n:
                    j=text.find('\n',i);j=n if j<0 else j
                    line=text[i:j].rstrip('\r');i=j+1
                    if line=='\\.':break
                else:raise GlobalValidityError('ARCHIVE_COPY_INCOMPLETE')
            continue
        m=re.match(r'[A-Za-z_][A-Za-z0-9_]*',text[i:])
        if m:tokens.append(m.group());i+=len(m.group())
        else:i+=1
    if start is not None:raise GlobalValidityError('ARCHIVE_INCOMPLETE_STATEMENT')
    return {'selectedStatements':out,'metaCommands':meta,'identityCommands':[r for r in out if r['category']=='identity'],'rawBytes':len(raw),'rawSha256':sha(raw)}

def offline():
    cases=[]
    def check(name,fn,expected):
        try:fn();actual=True
        except (ProofFailure,Failure,GlobalValidityError):actual=False
        assert actual==expected,(name,actual,expected)
        cases.append({'case':name,'expectedAccepted':expected,'actualAccepted':actual,'status':'PASS'})
    sample={'extensions':[{'name':n,'version':v,'schema':s,'owner':'boot'} for n,v,s in EXPECTED_SET],'members':[],'rawAcl':[],'expandedAcl':[]}
    for ext,counts in EXPECTED_COUNTS.items():
        for cls,count in counts.items():
            for i in range(count):sample['members'].append({'extension':ext,'class':cls,'identity':ext+cls+str(i),'subid':0,'owner':'boot','structure':{'bounded':True}})
    roles=[['boot',True]+[None]*9]
    check('fixed set positive',lambda:profile(sample,'boot',roles),True)
    check('plpgsql only unchanged branch',lambda:profile({'extensions':[]},'boot',roles),True)
