def docker(argv,data=None,timeout=300):
    p=subprocess.run(['docker',*argv],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=timeout)
    if p.returncode:raise GlobalValidityError('DRIVER_DOCKER_FAILED '+p.stderr.decode('utf8','replace')[:2000])
    return p.stdout

def write_private(name,raw):
    p=W/name;p.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
    fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
    with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
    return {'path':str(p),'bytes':len(raw),'sha256':sha(raw)}

